CREATE TABLE CARDIAC_SURGERY_AND_PERFUSION_OUTCOME_ANALYSIS (
    RECORD_ID VARCHAR(10) NOT NULL UNIQUE,
    PATIENT_ID VARCHAR(10) PRIMARY KEY,
    AGE INT,
    SEX VARCHAR(1),
    WEIGHT_KG FLOAT,
    SURGERY_TYPE VARCHAR(50),
    CPB_TIME_MIN INT,
    CROSS_CLAMP_TIME_MIN INT,
    TEMPERATURE FLOAT,
    ICU_STAY_DAYS INT,
    VENTILATION_HOURS INT,
    TOTAL_COST FLOAT,
    OUTCOME VARCHAR(30),
    COMPLICATION VARCHAR(10),
    REOPERATION VARCHAR(10),
    AGE_GROUP VARCHAR(20)
);


SELECT*FROM CARDIAC_SURGERY_AND_PERFUSION_OUTCOME_ANALYSIS;

-- # AORTIC SURGERY HAS THE HIGHEST COMPLICATION RATE OF 14%
SELECT SURGERY_TYPE, COUNT(CASE WHEN OUTCOME='Complication'THEN 1 END)*100/COUNT(*) AS COMPLICATION_RATE
FROM CARDIAC_SURGERY_AND_PERFUSION_OUTCOME_ANALYSIS
GROUP BY SURGERY_TYPE;

-- # SENIORS HAS LONGEST ICU STAY OF 3.7 DAYS
SELECT AGE_GROUP, AVG(ICU_STAY_DAYS) AS AVG_ICU_STAY
FROM CARDIAC_SURGERY_AND_PERFUSION_OUTCOME_ANALYSIS
GROUP BY AGE_GROUP;

SELECT * 
FROM CARDIAC_SURGERY_AND_PERFUSION_OUTCOME_ANALYSIS
WHERE CPB_TIME_MIN>150 AND OUTCOME='Complication';

-- # AORTIC SURGERY HAS HIGHEST AVG TOTAL COST
SELECT SURGERY_TYPE, AVG(TOTAL_COST) AS AVG_TOTAL_COST
FROM CARDIAC_SURGERY_AND_PERFUSION_OUTCOME_ANALYSIS
GROUP BY SURGERY_TYPE;

-- # AORTIC SURGERY HAS LONGEST VENT_TIME OF 14.97 HOURS
SELECT SURGERY_TYPE, AVG(VENTILATION_HOURS) AS AVG_VENT_HOURS
FROM CARDIAC_SURGERY_AND_PERFUSION_OUTCOME_ANALYSIS
GROUP BY SURGERY_TYPE
ORDER BY SURGERY_TYPE DESC;

-- # 9.6% PATIENT HAD COMPLICATION
SELECT  COUNT(CASE WHEN OUTCOME='Complication' THEN 1 END)*100/COUNT(*) AS COMPLICATION_RATE
FROM CARDIAC_SURGERY_AND_PERFUSION_OUTCOME_ANALYSIS;

SELECT*
FROM CARDIAC_SURGERY_AND_PERFUSION_OUTCOME_ANALYSIS
WHERE AGE_GROUP='NULL'; 
